import type { ExtractParams } from './types.ts';
import type { Param, Query } from './url.ts';

/**
 * The app's named routes — generated by `bespoke route:types` into `bootstrap/routes.ts` (committed, like
 * `bootstrap/database.d.ts`), merged in by declaration:
 *
 * ```ts
 * declare module '@bespokecore/router' {
 *   interface Routes {
 *     'user-profile.update': { method: 'put'; path: '/users/:user'; controller: typeof UpdateUserProfileController };
 *   }
 * }
 * ```
 *
 * Every API that takes a route name checks it against this interface — `redirect().route()`, `router.url()`,
 * signed URLs, `route()`, `<Link route>` and `useForm(name, …)` in the browser. Until something is generated,
 * names are plain strings, so packages type-check without an app.
 */
export interface Routes {}

/** What `bespoke route:types` writes per route. */
export interface RouteEntry {
  /** Lower case; a union for routes with several methods (`Route.match`). */
  readonly method: string;
  /** The full pattern, e.g. `/users/:user/links/:link?`. */
  readonly path: string;
  /** The controller class (`typeof …`) — absent for closures. Gives `useForm(name)` its fields. */
  readonly controller?: unknown;
  /** `false`: kept from the browser (API routes, `clientRoutes.except`). */
  readonly browser?: false;
}

type Registered = [keyof Routes] extends [never] ? false : true;

/** A route name of the app — any string while no routes are generated. */
export type RouteName = Registered extends true ? keyof Routes & string : string;

/** Names the browser knows: without API routes and `except` patterns (see `bespoke route:types`). */
export type BrowserRouteName = Registered extends true
  ? { [N in keyof Routes]: Routes[N] extends { readonly browser: false } ? never : N }[keyof Routes] & string
  : string;

/**
 * The constraint of a route-name type parameter: the names (for completions) plus any string, so a wrong one
 * reaches {@link CheckRouteName} — which explains it — instead of failing the constraint with the whole union.
 */
export type RouteNameInput = RouteName | (string & {});

/** {@link RouteNameInput} for the browser. */
export type BrowserRouteNameInput = BrowserRouteName | (string & {});

/**
 * `N` when it is a route name; otherwise a message the compiler shows as the expected type:
 * `'user-profile.shwo' is not a route name — did you mean user-profile.show, …?`.
 */
export type CheckRouteName<N extends string> = string extends N
  ? RouteName
  : N extends RouteName
    ? N
    : `'${N}' is not a route name${Suggest<N, RouteName>}`;

/** Like {@link CheckRouteName}, for the browser: API routes and `except` patterns are named as such. */
export type CheckBrowserRouteName<N extends string> = string extends N
  ? BrowserRouteName
  : N extends BrowserRouteName
    ? N
    : N extends RouteName
      ? `'${N}' is not sent to the browser — API routes and clientRoutes.except stay on the server`
      : `'${N}' is not a route name${Suggest<N, BrowserRouteName>}`;

type Entry<N> = N extends keyof Routes ? Routes[N] : never;

/** The path parameters of route `N`: `{ user: Param }`, optional ones optional. Any for a name that is not one literal. */
export type ParamsOf<N extends string> = true extends IsUnion<N>
  ? Record<string, Param>
  : N extends keyof Routes
  ? Entry<N> extends { readonly path: infer P extends string }
    ? ParamValues<ExtractParams<P>>
    : Record<string, Param>
  : Record<string, Param>;

type ParamValues<T> = { [K in keyof T]: Param } & {};

/** The HTTP method of route `N`, lower case (`'put'`). */
export type MethodOf<N extends string> = Entry<N> extends { readonly method: infer M extends string } ? M : string;

/** The controller class behind route `N` (`typeof UpdateUserProfileController`), or `never` for a closure. */
export type ControllerOf<N extends string> = Entry<N> extends { readonly controller: infer C } ? C : never;

type IsUnion<T, U = T> = T extends unknown ? ([U] extends [T] ? false : true) : never;

/**
 * The arguments after a route name: its path parameters — required when the path has required ones — and a
 * query. A name that is not one literal (a `RouteName` variable) takes any parameters: they are checked at runtime.
 *
 * ```ts
 * redirect().route('user-profile.show', { user: 7 }, { tab: 'links' });   // → /users/7?tab=links
 * ```
 */
export type RouteArgs<N extends string> = {} extends ParamsOf<N> ? [params?: ParamsOf<N>, query?: Query] : [params: ParamsOf<N>, query?: Query];

// -- "Did you mean …?" ---------------------------------------------------------------------------------------

/** `user-profile.links.store` → `user-profile.links`; `home` → `''`. */
type Parent<N extends string, Sep extends string, Done extends string = ''> = N extends `${infer Head}${Sep}${infer Tail}`
  ? Parent<Tail, Sep, Done extends '' ? Head : `${Done}${Sep}${Head}`>
  : Done;

type LastSegment<N extends string, Sep extends string> = N extends `${string}${Sep}${infer Tail}` ? LastSegment<Tail, Sep> : N;

/** Names next to `N` (same parent, no deeper), preferring those whose last part starts with the same letter. */
type Siblings<N extends string, Names extends string, Sep extends string> =
  Parent<N, Sep> extends infer P extends string
    ? P extends ''
      ? never
      : Exclude<Extract<Names, `${P}${Sep}${string}`>, `${P}${Sep}${string}${Sep}${string}`> extends infer Near extends string
        ? LastSegment<N, Sep> extends `${infer First}${string}`
          ? [Extract<Near, `${P}${Sep}${First}${string}`>] extends [never]
            ? Near
            : Extract<Near, `${P}${Sep}${First}${string}`>
          : Near
        : never
    : never;

type UnionToIntersection<U> = (U extends unknown ? (x: () => U) => void : never) extends (x: infer I) => void ? I : never;
type LastOf<U> = UnionToIntersection<U> extends () => infer R ? R : never;

/** Joins a union of names: `a, b, c` (at most five, then `…`). */
type Join<U extends string, Count extends unknown[] = [], Done extends string = ''> = [U] extends [never]
  ? Done
  : Count['length'] extends 5
    ? `${Done}, …`
    : LastOf<U> extends infer L extends string
      ? Join<Exclude<U, L>, [...Count, L], Done extends '' ? L : `${L}, ${Done}`>
      : Done;

/** ` — did you mean a, b?` for names next to `N`, or nothing. */
export type Suggest<N extends string, Names extends string, Sep extends string = '.'> = [Siblings<N, Names, Sep>] extends [never]
  ? ''
  : ` — did you mean ${Join<Siblings<N, Names, Sep>>}?`;
